from pathlib import Path

filename = "order_summary.xlsx"
start = Path.cwd().resolve()

matches = []
for root in [start, *start.parents]:
    matches = [
        path.resolve()
        for path in root.rglob(filename)
        if path.is_file()
    ]
    if matches:
        break

matches = list(dict.fromkeys(matches))

if not matches:
    raise FileNotFoundError(
        f"Could not find {filename} under {start} or its parent directories."
    )

if len(matches) > 1:
    choices = "\n".join(f"- {path}" for path in matches)
    raise RuntimeError(
        "Multiple matching workbooks were found. Set INPUT explicitly:\n"
        + choices
    )

INPUT = matches[0]
print(f"Using workbook: {INPUT}")

import pandas as pd

workbook = pd.ExcelFile(INPUT, engine="openpyxl")

print(f"Workbook: {INPUT}")
print(f"Worksheets ({len(workbook.sheet_names)}):")
for sheet_name in workbook.sheet_names:
    frame = pd.read_excel(
        INPUT,
        sheet_name=sheet_name,
        engine="openpyxl",
    )
    print(
        f"- {sheet_name}: {len(frame):,} rows, "
        f"{len(frame.columns):,} columns"
    )
    print(f"  Columns: {list(frame.columns)}")
